import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { CahierPedagogiqueService } from '../../core/services/cahier-pedagogique.service';
import { ProfService } from '../../core/services/prof.service';

@Component({
  selector: 'app-prof-public',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './prof-public.component.html',
  styleUrls: ['./prof-public.component.scss']
})
export class ProfPublicComponent implements OnInit {
  classes: any[] = [];
  cahiers: any[] = [];
  pagedCahiers: any[] = [];
  selectedClassId: number | null = null;
  selectedFile: File | null = null;
  fileName = '';
  uploading = false;

  // 🔹 Pagination
  currentPage = 1;
  pageSize = 6;
  totalPages = 0;

  constructor(
    private cahierService: CahierPedagogiqueService,
    private profService: ProfService,
    private router: Router
  ) {}

  ngOnInit() {
    this.loadClasses();
  }

  gotoClasses() {
    this.router.navigate(['/dashboard']);
  }

  /** 🔹 Charger les classes du professeur connecté */
  loadClasses() {
    this.profService.getMyClasses().subscribe({
      next: data => (this.classes = data || []),
      error: err => console.error('Erreur chargement classes:', err)
    });
  }

  /** 🔹 Charger les cahiers d’une classe */
  loadCahiers() {
    if (!this.selectedClassId) return;

    this.cahierService.getCahiersByClass(this.selectedClassId).subscribe({
      next: res => {
        this.cahiers = (res || []).sort(
          (a: any, b: any) =>
            new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
        );
        this.currentPage = 1;
        this.updatePagination();
      },
      error: err => console.error('Erreur chargement cahiers:', err)
    });
  }

  /** 🔹 Gérer la pagination */
  updatePagination() {
    this.totalPages = Math.ceil(this.cahiers.length / this.pageSize);
    const start = (this.currentPage - 1) * this.pageSize;
    const end = start + this.pageSize;
    this.pagedCahiers = this.cahiers.slice(start, end);
  }

  changePage(page: number) {
    if (page < 1 || page > this.totalPages) return;
    this.currentPage = page;
    this.updatePagination();
  }

  /** 🔹 Sélection du fichier */
  onFileSelected(event: any) {
    this.selectedFile = event.target.files[0];
  }

  /** 🔹 Upload du cahier */
  uploadCahier() {
    if (!this.selectedFile || !this.selectedClassId) {
      alert('Veuillez choisir une classe et un fichier.');
      return;
    }

    this.uploading = true;
    this.cahierService.uploadCahier(this.selectedFile, this.selectedClassId, this.fileName).subscribe({
      next: () => {
        this.uploading = false;
        this.fileName = '';
        this.selectedFile = null;
        this.loadCahiers();
      },
      error: err => {
        console.error('Erreur upload:', err);
        this.uploading = false;
      }
    });
  }

  /** 🔹 Suppression d’un cahier */
  deleteCahier(id: number) {
    if (!confirm('Voulez-vous vraiment supprimer ce cahier ?')) return;

    this.cahierService.deleteCahier(id).subscribe({
      next: () => {
        this.cahiers = this.cahiers.filter(c => c.id !== id);
        this.updatePagination();
        alert('🗑️ Cahier supprimé avec succès');
      },
      error: err => console.error('Erreur suppression:', err)
    });
  }
}
<div class="dashboard-container py-5">
  <!-- 🧭 En-tête -->
  <div
    class="dashboard-header d-flex flex-wrap justify-content-between align-items-center mb-4 p-3 rounded shadow-sm bg-light border">
    <div class="mb-3 mb-md-0">
      <h1 class="dashboard-title fw-bold text-primary mb-1">
        <i class="bi bi-journal-text me-2"></i> Cahier pédagogique
      </h1>
      <p class="dashboard-subtitle text-muted mb-0">
        📖 Espace du professeur – gérez vos séances, descriptions et fichiers.
      </p>
    </div>

    <div class="d-flex flex-wrap gap-2">
      <button class="btn btn-outline-primary d-flex align-items-center px-3" (click)="gotoClasses()">
        <i class="bi bi-speedometer2 me-2"></i>
        <span>Tableau de bord</span>
      </button>
    </div>
  </div>

  <!-- 🧩 Section Upload -->
  <div class="row g-4 align-items-start">
    <div class="col-12 col-lg-4">
      <div class="card p-4 shadow-sm">
        <h3 class="card-title mb-3">📤 Ajouter un cahier pédagogique</h3>

        <form (ngSubmit)="uploadCahier()" class="upload-form">
          <div class="mb-3">
            <label class="form-label">Classe</label>
            <select
              class="form-select"
              [(ngModel)]="selectedClassId"
              name="classId"
              (change)="loadCahiers()"
              required>
              <option [ngValue]="null">-- Sélectionner une classe --</option>
              <option *ngFor="let c of classes" [value]="c.id">{{ c.name }}</option>
            </select>
          </div>

          <div class="mb-3">
            <label class="form-label">Titre</label>
            <input
              class="form-control"
              [(ngModel)]="fileName"
              name="fileName"
              placeholder="Ex: Chapitre 2 – Les Réseaux"
              required />
          </div>

          <div class="mb-3">
            <label class="form-label">Description</label>
            <textarea
              class="form-control"
              [(ngModel)]="description"
              name="description"
              placeholder="Ex: Introduction aux modèles OSI et TCP/IP"
              rows="2"></textarea>
          </div>

          <div class="mb-3">
            <label class="form-label">Fichier</label>
            <input type="file" class="form-control" (change)="onFileSelected($event)" required />
          </div>

          <button class="btn btn-primary w-100" [disabled]="uploading">
            <ng-container *ngIf="!uploading">
              <i class="bi bi-cloud-upload me-2"></i> Uploader
            </ng-container>
            <ng-container *ngIf="uploading">
              <span class="spinner-border spinner-border-sm"></span> Upload en cours...
            </ng-container>
          </button>
        </form>
      </div>
    </div>

    <!-- 📚 Liste des cahiers -->
    <div class="col-12 col-lg-8">
      <div class="card p-4 shadow-sm">
        <h3 class="section-title mb-4 text-center text-primary">
          📘 Cahiers de la classe sélectionnée
        </h3>

        <div *ngIf="pagedCahiers.length > 0; else noCahiers" class="files-grid">
          <div class="file-card shadow-sm" *ngFor="let cahier of pagedCahiers">
            <div class="file-header d-flex justify-content-between align-items-center mb-2">
              <h5 class="file-title text-primary">
                <i class="bi bi-journal-text me-1"></i> {{ cahier.fileName }}
              </h5>
            </div>

            <p *ngIf="cahier.description" class="file-description text-muted small mb-2">
              {{ cahier.description }}
            </p>

            <p class="file-date text-muted small mb-3">
              <i class="bi bi-calendar-event me-1"></i>
              Ajouté le {{ cahier.createdAt | date: 'dd MMM yyyy, HH:mm' }}
            </p>

            <div class="file-actions d-grid gap-2">
              <a
                [href]="cahier.fileUrl"
                target="_blank"
                rel="noopener noreferrer"
                class="btn btn-outline-success btn-sm">
                <i class="bi bi-box-arrow-up-right me-1"></i> Ouvrir / Télécharger
              </a>

              <button
                class="btn btn-outline-danger btn-sm"
                (click)="deleteCahier(cahier.id)">
                <i class="bi bi-trash me-1"></i> Supprimer
              </button>
            </div>
          </div>
        </div>

        <!-- 🔢 Pagination -->
        <nav *ngIf="totalPages > 1" class="mt-4">
          <ul class="pagination justify-content-center">
            <li class="page-item" [class.disabled]="currentPage === 1">
              <button class="page-link" (click)="changePage(currentPage - 1)">Précédent</button>
            </li>

            <li
              class="page-item"
              *ngFor="let page of [].constructor(totalPages); let i = index"
              [class.active]="currentPage === i + 1">
              <button class="page-link" (click)="changePage(i + 1)">{{ i + 1 }}</button>
            </li>

            <li class="page-item" [class.disabled]="currentPage === totalPages">
              <button class="page-link" (click)="changePage(currentPage + 1)">Suivant</button>
            </li>
          </ul>
        </nav>

        <!-- 📭 Aucun cahier -->
        <ng-template #noCahiers>
          <div class="alert alert-info text-center mt-4">
            📭 Aucun cahier pédagogique n’a encore été uploadé pour cette classe.
          </div>
        </ng-template>
      </div>
    </div>
  </div>
</div>
